<script>
    function editarMatricula(boton) {
        document.getElementById('em-id').value = boton.dataset.id;
        document.getElementById('em-periodo').value = boton.dataset.periodo;
        document.getElementById('em-seccion').value = boton.dataset.seccion;
        document.getElementById('em-fecha').value = boton.dataset.fecha;
        document.getElementById('em-codigo').value = boton.dataset.codigo;
        document.getElementById('em-estado').value = boton.dataset.estado;
        document.getElementById('modal-editar-matricula').classList.remove('hidden');
    }
</script>
