<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('form-promocion-v2');if(!form)return;const alumnos=<?= json_encode($promocion ?: [], JSON_HEX_APOS | JSON_HEX_QUOT) ?>,secciones=<?= json_encode($opciones['secciones'], JSON_HEX_APOS | JSON_HEX_QUOT) ?>;form.querySelectorAll('tbody tr').forEach((fila,indice)=>{const alumno=alumnos[indice];if(!alumno||!alumno.id_grado_siguiente)return;const continuar=fila.querySelector('input[name^="promover"]'),retirar=fila.querySelector('input[name="retirar[]"]'),destino=fila.querySelector('select[name^="seccion_destino"]'),contenedor=fila.cells[4].querySelector('div'),repetir=document.createElement('input'),etiqueta=document.createElement('label'),seccionRepite=document.createElement('select');repetir.type='checkbox';repetir.name=`repetir[${alumno.id_matricula}]`;repetir.value='1';etiqueta.className='inline-flex items-center gap-2 text-sm text-violet-700';etiqueta.append(repetir,document.createTextNode(' Repite el grado'));seccionRepite.name=`seccion_repite[${alumno.id_matricula}]`;seccionRepite.className='form-input mt-1 hidden';seccionRepite.disabled=true;const opciones=secciones.filter(s=>Number(s.id_grado)===Number(alumno.id_grado)).sort((a,b)=>Number(b.id_seccion===alumno.id_seccion_origen)-Number(a.id_seccion===alumno.id_seccion_origen));opciones.forEach((s,i)=>{const o=document.createElement('option');o.value=s.id_seccion;o.textContent=s.nombre;o.selected=i===0;seccionRepite.appendChild(o);});contenedor.prepend(etiqueta);contenedor.appendChild(seccionRepite);const ocultarRepite=()=>{repetir.checked=false;seccionRepite.disabled=true;seccionRepite.classList.add('hidden');};repetir.addEventListener('change',()=>{if(repetir.checked){continuar.checked=false;retirar.checked=false;destino.disabled=true;destino.required=false;destino.classList.add('hidden');seccionRepite.disabled=false;seccionRepite.classList.remove('hidden');}else{seccionRepite.disabled=true;seccionRepite.classList.add('hidden');}});continuar.addEventListener('change',()=>{if(continuar.checked){ocultarRepite();destino.classList.remove('hidden');}});retirar.addEventListener('change',()=>{if(retirar.checked)ocultarRepite();});});});</script>
<div id="modal-promocion-v2" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-8 max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"><div class="flex items-start justify-between gap-4"><div><h2 class="text-lg font-bold">Preparar promoción anual</h2><p class="mt-1 text-sm text-slate-500">Procesa todo el período o limita la promoción a un grado o sección.</p></div><button type="button" onclick="document.getElementById('modal-promocion-v2').classList.add('hidden')" class="rounded-lg p-2 hover:bg-slate-100"><i class="bi bi-x-lg"></i></button></div><?php $filtroActual=$_GET['promocion_filtro']??'TODO'; ?><form method="get" action="index.php" class="mt-5 grid gap-4 sm:grid-cols-2"><input type="hidden" name="url" value="matriculas"><label class="form-label">Período origen<select required name="promocion_origen" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['periodos_edicion'] as $periodo): ?><option value="<?= $periodo['id_periodo_academico'] ?>" <?= (int)($_GET['promocion_origen']??0)===(int)$periodo['id_periodo_academico']?'selected':'' ?>><?= htmlspecialchars($periodo['nombre'].' · '.$periodo['estado']) ?></option><?php endforeach; ?></select></label><label class="form-label">Período destino<select required name="promocion_destino" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['periodos_edicion'] as $periodo): ?><option value="<?= $periodo['id_periodo_academico'] ?>" <?= (int)($_GET['promocion_destino']??0)===(int)$periodo['id_periodo_academico']?'selected':'' ?>><?= htmlspecialchars($periodo['nombre'].' · '.$periodo['estado']) ?></option><?php endforeach; ?></select></label><label class="form-label sm:col-span-2">Alcance<select id="promocion-filtro" name="promocion_filtro" class="form-input" onchange="actualizarFiltroPromocion()"><option value="TODO" <?= $filtroActual==='TODO'?'selected':'' ?>>Todo el período</option><option value="GRADO" <?= $filtroActual==='GRADO'?'selected':'' ?>>Por grado</option><option value="SECCION" <?= $filtroActual==='SECCION'?'selected':'' ?>>Por sección</option></select></label><label id="campo-promocion-grado" class="form-label">Grado<select name="promocion_grado" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['grados'] as $grado): ?><option value="<?= $grado['id_grado'] ?>" <?= (int)($_GET['promocion_grado']??0)===(int)$grado['id_grado']?'selected':'' ?>><?= htmlspecialchars($grado['nombre']) ?></option><?php endforeach; ?></select></label><label id="campo-promocion-seccion" class="form-label">Sección<select name="promocion_seccion" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['secciones'] as $seccion): ?><option value="<?= $seccion['id_seccion'] ?>" <?= (int)($_GET['promocion_seccion']??0)===(int)$seccion['id_seccion']?'selected':'' ?>><?= htmlspecialchars($seccion['nombre']) ?></option><?php endforeach; ?></select></label><div class="flex justify-end gap-2 sm:col-span-2"><button type="button" onclick="document.getElementById('modal-promocion-v2').classList.add('hidden')" class="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-600">Cancelar</button><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Ver alumnos</button></div></form></div></div>
<?php if($promocion!==null): ?><section class="mt-6 overflow-hidden rounded-2xl border border-blue-200 bg-white shadow-sm"><div class="border-b border-blue-100 bg-blue-50 px-5 py-4"><h2 class="font-semibold text-blue-950">Promoción pendiente</h2><p class="text-sm text-blue-700">Se selecciona por defecto el grado siguiente. Para el último grado se recomienda egresar.</p></div><?php if(!$promocion): ?><p class="px-5 py-10 text-center text-slate-500">No hay alumnos activos pendientes para la selección realizada.</p><?php else: ?><form id="form-promocion-v2" method="post" action="index.php?url=matriculas_promover" class="overflow-x-auto" data-promocion-anual><?= campoCsrf() ?><input type="hidden" name="id_origen" value="<?= (int)$_GET['promocion_origen'] ?>"><input type="hidden" name="id_destino" value="<?= (int)$_GET['promocion_destino'] ?>"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-4">Continuar</th><th class="px-5 py-4">Alumno</th><th class="px-5 py-4">Sección actual</th><th class="px-5 py-4">Sección destino sugerida</th><th class="px-5 py-4">Decisión</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($promocion as $alumno): $esEgreso=empty($alumno['id_grado_siguiente']); ?><tr data-promocion-fila <?= $esEgreso?'data-egreso="1"':'' ?>><td class="px-5 py-4"><input type="checkbox" name="promover[<?= $alumno['id_matricula'] ?>]" value="1" <?= $esEgreso?'':'checked' ?>></td><td class="px-5 py-4"><strong><?= htmlspecialchars($alumno['alumno']) ?></strong><span class="block font-mono text-xs text-slate-500"><?= htmlspecialchars($alumno['codigo_alumno']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= htmlspecialchars($alumno['seccion_origen']) ?></td><td class="px-5 py-4"><?php if($esEgreso): ?><span class="text-sm font-medium text-blue-700">No existe grado siguiente</span><?php else: $primera=true; ?><select required name="seccion_destino[<?= $alumno['id_matricula'] ?>]" class="form-input mt-0"><?php foreach($opciones['secciones'] as $seccion): if((int)$seccion['id_grado']!==(int)$alumno['id_grado_siguiente']) continue; ?><option value="<?= $seccion['id_seccion'] ?>" <?= $primera?'selected':'' ?>><?= htmlspecialchars($seccion['nombre']) ?></option><?php $primera=false; endforeach; ?></select><?php endif; ?></td><td class="px-5 py-4"><div class="flex flex-col gap-2"><?php if($esEgreso): ?><label class="inline-flex items-center gap-2 text-sm font-medium text-blue-700"><input checked type="checkbox" name="egresar[]" value="<?= $alumno['id_matricula'] ?>"> Egresar (recomendado)</label><?php endif; ?><label class="inline-flex items-center gap-2 text-sm text-red-700"><input type="checkbox" name="retirar[]" value="<?= $alumno['id_matricula'] ?>"> Retirar</label></div></td></tr><?php endforeach; ?></tbody></table><div class="flex justify-end border-t bg-slate-50 p-4"><button class="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Procesar promoción</button></div></form><?php endif; ?></section><?php endif; ?>
<script>function actualizarFiltroPromocion(){const f=document.getElementById('promocion-filtro'),g=document.getElementById('campo-promocion-grado'),s=document.getElementById('campo-promocion-seccion');g.classList.toggle('hidden',f.value!=='GRADO');s.classList.toggle('hidden',f.value!=='SECCION');g.querySelector('select').required=f.value==='GRADO';s.querySelector('select').required=f.value==='SECCION';}actualizarFiltroPromocion();document.querySelectorAll('[data-promocion-fila]').forEach(fila=>{const c=fila.querySelector('input[name^="promover"]'),r=fila.querySelector('input[name="retirar[]"]'),e=fila.querySelector('input[name="egresar[]"]'),s=fila.querySelector('select');const sync=origen=>{if(origen===r&&r.checked){c.checked=false;if(e)e.checked=false;}if(e&&origen===e&&e.checked){c.checked=false;r.checked=false;}if(origen===c&&c.checked){r.checked=false;if(e)e.checked=false;}const activo=c.checked&&!r.checked&&!(e&&e.checked);if(s){s.disabled=!activo;s.required=activo;}};c.addEventListener('change',()=>sync(c));r.addEventListener('change',()=>sync(r));if(e)e.addEventListener('change',()=>sync(e));sync(e);});</script>
<div id="modal-promocion" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-8 max-w-xl rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Preparar promoción anual</h2><p class="mt-1 text-sm text-slate-500">Elige el período que termina y el período destino.</p><form method="get" action="index.php" class="mt-5 grid gap-4 sm:grid-cols-2"><input type="hidden" name="url" value="matriculas"><label class="form-label">Origen<select required name="promocion_origen" class="form-input"><option value="">Seleccione</option><?php foreach ($opciones['periodos_edicion'] as $periodo): ?><option value="<?= $periodo['id_periodo_academico'] ?>"><?= htmlspecialchars($periodo['nombre'] . ' · ' . $periodo['estado']) ?></option><?php endforeach; ?></select></label><label class="form-label">Destino<select required name="promocion_destino" class="form-input"><option value="">Seleccione</option><?php foreach ($opciones['periodos_edicion'] as $periodo): ?><option value="<?= $periodo['id_periodo_academico'] ?>"><?= htmlspecialchars($periodo['nombre'] . ' · ' . $periodo['estado']) ?></option><?php endforeach; ?></select></label><div class="sm:col-span-2 flex justify-end"><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Ver alumnos</button></div></form></div></div>
<?php if ($promocion !== null): ?><section class="mt-6 overflow-hidden rounded-2xl border border-blue-200 bg-white shadow-sm"><div class="border-b border-blue-100 bg-blue-50 px-5 py-4"><h2 class="font-semibold text-blue-950">Promoción pendiente</h2><p class="text-sm text-blue-700">Marca quienes continúan, selecciona su sección destino o marca Retirar.</p></div><?php if (!$promocion): ?><p class="px-5 py-10 text-center text-slate-500">No hay alumnos activos pendientes para esta combinación de períodos.</p><?php else: ?><form method="post" action="index.php?url=matriculas_promover" class="overflow-x-auto" data-promocion-anual><?= campoCsrf() ?><input type="hidden" name="id_origen" value="<?= (int) $_GET['promocion_origen'] ?>"><input type="hidden" name="id_destino" value="<?= (int) $_GET['promocion_destino'] ?>"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-4">Continuar</th><th class="px-5 py-4">Alumno</th><th class="px-5 py-4">Sección actual</th><th class="px-5 py-4">Sección destino</th><th class="px-5 py-4">Retirar</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($promocion as $alumno): ?><tr><td class="px-5 py-4"><input checked type="checkbox" name="promover[<?= $alumno['id_matricula'] ?>]" value="1"></td><td class="px-5 py-4"><strong><?= htmlspecialchars($alumno['alumno']) ?></strong><span class="block font-mono text-xs text-slate-500"><?= htmlspecialchars($alumno['codigo_alumno']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= htmlspecialchars($alumno['seccion_origen']) ?></td><td class="px-5 py-4"><select required name="seccion_destino[<?= $alumno['id_matricula'] ?>]" class="form-input mt-0"><option value="">Seleccione</option><?php foreach ($opciones['secciones'] as $seccion): ?><option value="<?= $seccion['id_seccion'] ?>"><?= htmlspecialchars($seccion['nombre']) ?></option><?php endforeach; ?></select></td><td class="px-5 py-4"><label class="inline-flex items-center gap-2 text-sm text-red-700"><input type="checkbox" name="retirar[]" value="<?= $alumno['id_matricula'] ?>"> Retirar</label></td></tr><?php endforeach; ?></tbody></table><div class="flex justify-end border-t bg-slate-50 p-4"><button class="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Procesar promoción</button></div></form><?php endif; ?></section><?php endif; ?><script>document.querySelectorAll('[data-promocion-anual] tbody tr').forEach(fila=>{const continuar=fila.querySelector('input[name^="promover"]'),retirar=fila.querySelector('input[name="retirar[]"]'),seccion=fila.querySelector('select');const sincronizar=()=>{const activo=continuar.checked&&!retirar.checked;seccion.disabled=!activo;seccion.required=activo;if(retirar.checked)continuar.checked=false;};continuar.addEventListener('change',sincronizar);retirar.addEventListener('change',sincronizar);sincronizar();});</script>
